CREATE OR REPLACE FUNCTION poems_search_vec_trg() RETURNS trigger AS $$
DECLARE aname text;
BEGIN
  SELECT name INTO aname FROM authors WHERE id = NEW.author_id;
  NEW.search_vec :=
    setweight(to_tsvector('simple', f_unaccent(coalesce(NEW.name, ''))), 'A') ||
    setweight(to_tsvector('simple', f_unaccent(coalesce(aname, ''))), 'B') ||
    setweight(to_tsvector('simple', f_unaccent(coalesce(NEW.content, ''))), 'C');
  RETURN NEW;
END $$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION authors_refresh_poems_search() RETURNS trigger AS $$
BEGIN
  UPDATE poems SET search_vec =
      setweight(to_tsvector('simple', f_unaccent(coalesce(name, ''))), 'A') ||
      setweight(to_tsvector('simple', f_unaccent(coalesce(NEW.name, ''))), 'B') ||
      setweight(to_tsvector('simple', f_unaccent(coalesce(content, ''))), 'C')
    WHERE author_id = NEW.id;
  RETURN NEW;
END $$ LANGUAGE plpgsql;
